add_action( 'pre_get_posts', 'perfectpixel_delay_posts_in_feeds' );

function perfectpixel_delay_posts_in_feeds( $query ) {
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_feed() || $query->is_comment_feed() ) {
		return;
	}
	$minutes = max( 0, (int) '{{feed_delay_minutes}}' );
	if ( ! $minutes ) {
		return;
	}
	$date_query   = (array) $query->get( 'date_query' );
	$date_query[] = array(
		'column' => 'post_date_gmt',
		'before' => gmdate( 'Y-m-d H:i:s', time() - $minutes * MINUTE_IN_SECONDS ),
	);
	$query->set( 'date_query', array_filter( $date_query ) );
}
